def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    if horizon <= 0:
        return []
    y = []
    for value in history:
        try:
            value = float(value)
            if math.isfinite(value):
                y.append(value)
        except Exception:
            pass
    if not y:
        return [0.0] * horizon
    if len(y) < 3:
        return [max(0.0, y[-1])] * horizon

    def median(values):
        values = sorted(values)
        n = len(values)
        if not n:
            return 0.0
        middle = n // 2
        return values[middle] if n % 2 else 0.5 * (values[middle - 1] + values[middle])

    recent_diffs = [y[i] - y[i - 1] for i in range(max(1, len(y) - 24), len(y))]
    local_scale = median([abs(v) for v in recent_diffs])
    jump_limit = max(0.03 * max(1.0, abs(y[-1])), 6.0 * local_scale, 1e-6)
    start = len(y) - 1
    while start > 0 and abs(y[start] - y[start - 1]) <= jump_limit:
        start -= 1
    segment = y[start:]
    if len(segment) < 8:
        segment = y[-min(24, len(y)):]

    def model(train, steps, block, shrink):
        diffs = [train[i] - train[i - 1] for i in range(1, len(train))]
        if not diffs:
            return [max(0.0, train[-1])] * steps
        block = min(block, len(diffs))
        new = median(diffs[-block:])
        if len(diffs) >= 2 * block:
            old = median(diffs[-2 * block:-block])
            acceleration = shrink * (new - old) / float(block)
        else:
            acceleration = 0.0
        acceleration_cap = max(abs(new) / 200.0, local_scale / 500.0)
        acceleration = max(-acceleration_cap, min(acceleration_cap, acceleration))
        if new < 0.0:
            new = min(new, -1e-12)
        elif new > 0.0:
            new = max(new, 1e-12)
        out = []
        level = train[-1]
        for k in range(1, steps + 1):
            increment = new + acceleration * k
            if new < 0.0:
                increment = min(0.0, increment)
            elif new > 0.0:
                increment = max(0.0, increment)
            level = max(0.0, level + increment)
            out.append(level)
        return out

    candidates = []
    for block in (6, 10, 14, 18):
        for shrink in (0.0, 0.25, 0.5, 1.0):
            errors = []
            for holdout in (6, 10, 14):
                cut = len(segment) - holdout
                if cut < max(8, block + 2):
                    continue
                predicted = model(segment[:cut], holdout, block, shrink)
                for actual, estimate in zip(segment[cut:], predicted):
                    errors.append(2.0 * abs(estimate - actual) / (abs(estimate) + abs(actual) + 1e-9))
            if errors:
                score = sum(errors) / len(errors) + 0.001 * shrink
                candidates.append((score, block, shrink))
    if not candidates:
        block = min(10, len(segment) - 1)
        shrink = 0.0
    else:
        _, block, shrink = min(candidates)
    return model(segment, horizon, block, shrink)
